repo_files.dataloader.py:
"""Batch DataLoader collecting IDs for single bulk query resolution."""

from typing import Any, Callable, Dict, List, Optional


class BatchDataLoader:
    def __init__(self, batch_fn: Callable[[List[str]], Dict[str, Any]]):
        self.batch_fn = batch_fn
        self._queue: list[str] = []
        self._cache: Dict[str, Any] = {}

    def load(self, key: str) -> None:
        if key not in self._cache and key not in self._queue:
            self._queue.append(key)

    def dispatch(self) -> None:
        if not self._queue:
            return
        results = self.batch_fn(self._queue)
        self._cache.update(results)
        # BUG: Clears _queue but fails to populate missing keys with None,
        # causing infinite re-fetching or KeyErrors on nonexistent keys!
        self._queue = []

    def get_result(self, key: str) -> Optional[Any]:
        return self._cache.get(key)

repo_files.resolver.py:
"""GraphQL schema field resolvers."""

from typing import Any, Dict, List, Optional
from dataloader import BatchDataLoader
from models import Author, Book


class BookResolver:
    def __init__(self, authors_db: Dict[str, Author]):
        self.db_query_count = 0
        def bulk_fetch_authors(keys: List[str]) -> Dict[str, Author]:
            self.db_query_count += 1
            return {k: authors_db[k] for k in keys if k in authors_db}
        self.loader = BatchDataLoader(bulk_fetch_authors)

    def resolve_author_for_book(self, book: Book) -> Optional[Author]:
        self.loader.load(book.author_id)
        return None  # Pending batch dispatch

repo_files.executor.py:
"""GraphQL query plan batch execution coordinator."""

from typing import Any, Dict, List
from models import Author, Book
from resolver import BookResolver


class QueryExecutor:
    def __init__(self, resolver: BookResolver):
        self.resolver = resolver

    def execute_books_query(self, books: List[Book]) -> List[Dict[str, Any]]:
        # Stage 1: Enqueue all author IDs
        for b in books:
            self.resolver.resolve_author_for_book(b)
        # Stage 2: Single batch dispatch
        self.resolver.loader.dispatch()
        # Stage 3: Assemble results
        out = []
        for b in books:
            author = self.resolver.loader.get_result(b.author_id)
            out.append({
                "title": b.title,
                "author_name": author.name if author else "Unknown",
            })
        return out

reference_fix.dataloader.py:
"""Batch DataLoader collecting IDs for single bulk query resolution."""

from typing import Any, Callable, Dict, List, Optional


class BatchDataLoader:
    def __init__(self, batch_fn: Callable[[List[str]], Dict[str, Any]]):
        self.batch_fn = batch_fn
        self._queue: list[str] = []
        self._cache: Dict[str, Any] = {}

    def load(self, key: str) -> None:
        if key not in self._cache and key not in self._queue:
            self._queue.append(key)

    def dispatch(self) -> None:
        if not self._queue:
            return
        keys_to_fetch = list(self._queue)
        self._queue = []
        results = self.batch_fn(keys_to_fetch)
        for k in keys_to_fetch:
            self._cache[k] = results.get(k, None)

    def get_result(self, key: str) -> Optional[Any]:
        return self._cache.get(key)
